import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
  assert.equal(total([{ price: 250, qty: 2 }, { price: 500, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const tenLines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(tenLines, 0.1), 8550);
});

test('bulk discount starts at 10 lines, not below', () => {
  const nineLines = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(nineLines, 0.1), 8100);
});

test('totals with a zero discount rate are unchanged', () => {
  const tenLines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
  assert.equal(total(tenLines, 0), 9500);
  assert.equal(total(tenLines), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
